actions.handler:
(e) => {
  const val = Number((e.target as HTMLSelectElement).value);
  if (
    val &&
    !createForm.copy_accounts_from_group_ids.includes(val)
  ) {
    createForm.copy_accounts_from_group_ids.push(val);
  }
  (e.target as HTMLSelectElement).value = '';
}

(e) => {
  const val = Number((e.target as HTMLSelectElement).value);
  if (
    val &&
    !editForm.copy_accounts_from_group_ids.includes(val)
  ) {
    editForm.copy_accounts_from_group_ids.push(val);
  }
  (e.target as HTMLSelectElement).value = '';
}

emit('update', {
                ...entry,
                billing_mode: $event as BillingMode,
                intervals: [],
                time_pricing: { ...entry.time_pricing, periods: [] },
              })

form.payment_recharge_fee_rate = Math.min(
  100,
  Math.max(
    0,
    Math.round(
      parseFloat(
        ($event.target as HTMLInputElement).value ||
          '0',
      ) * 100,
    ) / 100,
  ),
)
